local n={emit=0,snd=0,ring=0}
for _,d in ipairs(workspace:GetDescendants()) do
if d.Name=="CashInEmitter" then n.emit+=1 end
if d.Name=="CashInSound" then n.snd+=1 end
if d.Name=="CashInRing" then n.ring+=1 end
end
local names={}
for _,d in ipairs(workspace:GetDescendants()) do if d:IsA("BasePart") and d.Name:lower():find("collect") then table.insert(names,d:GetFullName()) end end
n.collectors=names
return game:GetService("HttpService"):JSONEncode(n)

local c=workspace.Plots.Plot1.Collector
local t={}
for _,ch in ipairs(c:GetChildren()) do table.insert(t,ch.Name.."|"..ch.ClassName) end
local ring=workspace.Plots.Plot1:FindFirstChild("CashInRing")
local cfg=require(game.ReplicatedStorage.CashInConfig)
return game:GetService("HttpService"):JSONEncode({children=t,ring=ring and ring:GetFullName(),sid=tostring(cfg.CASHIN_SOUND_ID),maxp=tostring(cfg.MAX_POPUPS_PER_SECOND)})

local r={}
for _,d in workspace:GetDescendants() do if d:IsA("ParticleEmitter") then table.insert(r,d:GetFullName().." rate="..d.Rate) end end
local ga=require(game.ReplicatedStorage.GameAssets)
local keys={}
for k in pairs(ga) do table.insert(keys,k) end
local plaza=workspace:FindFirstChild("Plaza")
return game:GetService("HttpService"):JSONEncode({r=r,keys=keys,plaza=plaza~=nil,spout=plaza and plaza:FindFirstChild("Spout")~=nil})
